const log = document.getElementById('log');

// nys-change fires once for each selection, drop, or removal. `files` holds
// the whole current selection.
document.querySelectorAll('nys-fileinput').forEach((input) => {
  input.addEventListener('nys-change', (e) => {
    const names = e.detail.files.map((file) => file.name);
    log.textContent = `${input.label}: ${names.join(', ') || '(no files)'}`;
  });
});
